generate_fibonacci &lt;- function(limit) {
  fib_sequence &lt;- c(0, 1)
  next_value &lt;- fib_sequence[1] + fib_sequence[2]
    while (next_value &lt;= limit) {
    fib_sequence &lt;- c(fib_sequence, next_value)
    next_value &lt;- tail(fib_sequence, n = 1) + tail(fib_sequence, n = 2)[1]
    }
    return(fib_sequence)
}
